def _ledger(data, revision_priority, tax_base, refund):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for pos, event in enumerate(data["events"]):
        if event.get("sequence", 0) > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(pos))
        if revision_priority == "sequence_first":
            key = (event.get("sequence", 0), event.get("revision", 0), pos)
        else:
            key = (event.get("revision", 0), pos)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), mode)
        base = net if tax_base == "discounted" else raw
        tax = _round(base * event.get("tax_bp", 0), mode)
        amount = net + tax
        if refund and event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _ledger_solver(priority, base, refund):
    return lambda data: _ledger(data, priority, base, refund)


def _resolver(data):
    packages = data["packages"]
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    constraints = {name: (bounds[0], bounds[1])
                   for name, bounds in data["roots"].items()}
    best = None
    best_vector = None
    names = sorted(packages, reverse=True)

    def active_deps(row):
        return [dep for dep in row.get("deps", [])
                if not dep.get("feature") or dep["feature"] in features]

    def acyclic(edges):
        active, done = set(), set()

        def visit(name):
            if name in active:
                return False
            if name in done:
                return True
            active.add(name)
            for other in edges.get(name, ()):
                if not visit(other):
                    return False
            active.remove(name)
            done.add(name)
            return True

        return all(visit(name) for name in edges)

    def search(installed, limits, edges):
        nonlocal best, best_vector
        for name, version in installed.items():
            if name not in limits or not (limits[name][0] <= version <= limits[name][1]):
                return

        pending = [name for name in limits if name not in installed]
        if not pending:
            if not acyclic(edges):
                return
            vector = tuple(installed.get(name, -1) for name in names)
            if best_vector is None or vector > best_vector:
                best_vector, best = vector, dict(installed)
            return

        name = max(pending)
        low, high = limits[name]
        rows = [row for row in packages[name]
                if low <= row["version"] <= high
                and row["version"] not in blocked.get(name, [])
                and (name not in pins or row["version"] == pins[name])]
        for row in rows:
            version = row["version"]
            next_installed = dict(installed)
            next_installed[name] = version
            next_limits = dict(limits)
            next_edges = dict(edges)
            deps = active_deps(row)
            next_edges[name] = [dep["name"] for dep in deps]
            valid = True
            for dep in deps:
                dep_name = dep["name"]
                lo, hi = dep["min"], dep["max"]
                if dep_name in next_limits:
                    old_lo, old_hi = next_limits[dep_name]
                    lo, hi = max(lo, old_lo), min(hi, old_hi)
                if lo > hi:
                    valid = False
                    break
                next_limits[dep_name] = (lo, hi)
            if valid:
                search(next_installed, next_limits, next_edges)

    search({}, constraints, {})
    return {"error": "unsatisfiable"} if best is None else {"versions": best}


def _scheduler(data):
    from itertools import combinations

    jobs = [job for job in data["jobs"]
            if job["id"] not in data.get("blocked", [])]
    k = data["k"]
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    best_ids = None
    best_value = None

    for subset in combinations(jobs, k):
        ids = tuple(sorted(job["id"] for job in subset))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not (bounds[0] <= counts.get(group, 0) <= bounds[1])
               for group, bounds in quotas.items()):
            continue
        starts = sorted((job["start"], job["end"]) for job in subset)
        if any(sum(start <= t < end for start, end in starts) > 2
               for t in {point for interval in starts for point in interval}):
            continue
        value = sum(job["value"] for job in subset)
        if (best_value is None or value > best_value
                or (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids

    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _routes(data):
    import heapq

    required = data.get("required", [])
    indices = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1

    def add_visit(mask, node):
        if node in indices:
            mask |= 1 << indices[node]
        return mask

    source = data["source"]
    start_state = (source, add_visit(0, source), data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                duration = max(1, edge["duration"] - edge.get("discount", 0))
                durations.append((duration, remaining - 1))
            for duration, left in durations:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = add_visit(mask, next_node)
                next_state = (next_node, next_mask, left)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time,) + next_state)
    return {"arrival": None}


